@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with("."):
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var a: Array = []
	_walk("assets", a)
	var non_import := 0
	var imp := 0
	var uid := 0
	var ext_count := {}
	for f in a:
		var e := String(f).get_extension()
		ext_count[e] = int(ext_count.get(e, 0)) + 1
		if e == "import":
			imp += 1
		elif e == "uid":
			uid += 1
		else:
			non_import += 1
	var res := "COUNT assets_files=" + str(a.size()) + " imports=" + str(imp) + " uids=" + str(uid) + " sources=" + str(non_import) + " | top: "
	var arr: Array = []
	for k in ext_count.keys():
		arr.append(str(ext_count[k]) + " " + String(k))
	arr.sort_custom(func(x, y): return String(x).split(" ")[0].to_int() > String(y).split(" ")[0].to_int())
	for i in range(0, mini(8, arr.size())):
		res += String(arr[i]) + "; "
	return res
